  .evp{--g:hsl(var(--primary));--bd:hsl(var(--border));--mut:hsl(var(--muted-foreground));background:hsl(var(--background));padding:8rem 1rem 5rem;min-height:70vh;color:hsl(var(--foreground))}
  .evp *{box-sizing:border-box}
  .evp-wrap{max-width:72rem;margin:0 auto}
  .evp-eyebrow{font-size:.75rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin:0 0 .75rem}
  .evp h1{font-family:var(--font-display),Georgia,serif;font-size:clamp(2rem,5vw,3rem);line-height:1.08;margin:0 0 1rem;font-weight:500}
  .evp h2{font-family:var(--font-display),Georgia,serif;font-size:1.5rem;margin:0 0 .5rem;font-weight:500}
  .evp p{line-height:1.6}
  .evp-lead{font-size:1.05rem;color:var(--mut);max-width:38rem}
  .evp-grid2{display:grid;gap:1.25rem;grid-template-columns:1fr}
  @media(min-width:768px){.evp-grid2{grid-template-columns:1fr 1fr}}
  .evp-card{background:#fff;border:1px solid var(--bd);border-radius:1rem;padding:1.5rem}
  .evp-btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;min-height:44px;padding:.7rem 1.4rem;border-radius:999px;font-weight:600;font-size:.95rem;border:1px solid var(--g);background:var(--g);color:hsl(var(--primary-foreground));cursor:pointer;text-decoration:none}
  .evp-btn--ghost{background:#fff;color:var(--g)}
  .evp-btn[disabled]{opacity:.5;cursor:not-allowed}
  .evp-row{display:flex;flex-wrap:wrap;gap:.75rem;align-items:center}
  .evp-field{display:block;margin-bottom:.9rem}
  .evp-field span{display:block;font-size:.85rem;font-weight:600;margin-bottom:.3rem}
  .evp input,.evp select,.evp textarea{width:100%;font:inherit;font-size:16px;padding:.7rem .85rem;border:1px solid var(--bd);border-radius:.6rem;background:#fff}
  .evp-badge{display:inline-block;font-size:.75rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:.3rem .7rem;border-radius:999px;background:hsl(var(--primary)/.1);color:var(--g)}
  .evp-builder{display:grid;gap:1.5rem;grid-template-columns:1fr;align-items:start}
  @media(min-width:1024px){.evp-builder{grid-template-columns:minmax(0,1fr) 22rem}}
  .evp-list{display:grid;gap:.6rem}
  .evp-item{display:grid;grid-template-columns:56px minmax(0,1fr) auto;gap:.85rem;align-items:center;background:#fff;border:1px solid var(--bd);border-radius:.85rem;padding:.6rem .8rem}
  .evp-item img{width:56px;height:56px;object-fit:contain;border-radius:.5rem;background:#f6f6f2}
  .evp-item__t{font-weight:600;font-size:.95rem;line-height:1.3}
  .evp-item__p{font-size:.85rem;color:var(--mut)}
  .evp-item__p s{margin-right:.35rem}
  .evp-item__p b{color:var(--g);font-weight:700}
  .evp-item select{margin-top:.35rem;padding:.4rem .5rem;font-size:14px}
  .evp-qty{display:flex;align-items:center;border:1px solid var(--bd);border-radius:999px;overflow:hidden}
  .evp-qty button{width:40px;height:40px;border:0;background:#fff;font-size:1.2rem;cursor:pointer}
  .evp-qty input{width:44px;border:0;text-align:center;padding:0;font-size:16px}
  .evp-panel{position:sticky;top:6.5rem}
  .evp-lines{list-style:none;margin:0 0 1rem;padding:0;max-height:16rem;overflow:auto}
  .evp-lines li{display:flex;justify-content:space-between;gap:.75rem;font-size:.9rem;padding:.4rem 0;border-bottom:1px solid var(--bd)}
  .evp-tot{display:flex;justify-content:space-between;font-weight:700;margin:.4rem 0}
  .evp-note{font-size:.8rem;color:var(--mut)}
  .evp-link{display:flex;gap:.5rem;margin-top:.75rem}
  .evp-link input{font-size:14px}
  .evp-msg{padding:.8rem 1rem;border-radius:.6rem;background:hsl(var(--primary)/.08);color:var(--g);font-size:.9rem;margin:1rem 0}
  .evp-hide{display:none!important}

